    /// A query has been successfully executed and the server is sending back a partial response.
    SuccessResponsePartial,
}

impl Deserialize for ResponseType {
    fn deserialize<D: Deserializer>(deserializer: &mut D) -> Result<ResponseType, D::Error> {
        deserializer.deserialize(ResponseTypeVisitor)
    }
}

struct ResponseTypeVisitor;

impl de::Visitor for ResponseTypeVisitor {
    type Value = ResponseType;

    fn visit_u64<E: de::Error>(&mut self, value: u64) -> Result<Self::Value, E

