		ph.publish(addr, m.Body)
	case ModeHostPool:
		addr := ph.hostPool.Get()
		ph.publish(addr, m.Body)
	}

	if *statusEvery > 0 {
		ph.timermetrics.Record(time.Since(startTime))
		ph.counter++
		if ph.counter%uint64(*statusEvery) == 0 {
			log.Printf("--- PublishHandler Stats ---")
