func (ph *PublishHandler) publish(address string, body []byte) {
	var err error
	var req *http.Request
	var resp *http.Response

	startTime := time.Now()
	urlStr := fmt.Sprintf("%s/%s", address, url.QueryEscape(string(body)))

	if len(postAddrs) > 0 {
