// Pack takes a slice of arguments and packs them into a byte slice
// according to the ABI specification.
func Pack(args ...interface{}) ([]byte, error) {
	var (
		data []byte
		err  error
	)

	for _, arg := range args {
		var encoded []byte
		encoded, err = Encode(arg)
		if err != nil {
			return nil, err
		}
		data = append(data, encoded...)
	}

	return data, nil
}

