func Get(r, c int) *Matrix {
	if r*c > poolSize {
		return NewMatrix(r, c)
	}
	m := pool.Get().(*Matrix)
	m.Reuse()
	return m
}

// Put a matrix back into the pool.
func Put(m *Matrix) {
	if m.Cap() > poolSize {
		return
	}
	pool.Put(m)
}

// Reuse resets the matrix to be empty.
