// controlBuffer is a buffer for control frames.
type controlBuffer struct {
	mu   sync.Mutex
	cond *sync.Cond // condition variable to signal when there's data

	// items are control frames.
	items []interface{}
}

func newControlBuffer() *controlBuffer {
	cb := &controlBuffer{}
	cb.cond = sync.NewCond(&cb.mu)
	return cb
}

// Add adds a control frame to the buffer.
func (cb *controlBuffer) Add(item interface{}) {
	cb.mu.Lock()
	defer cb.mu.Unlock()
	cb.items = append(cb.items, item)
	cb.cond.Signal()
}

