			}
		} else if env.Name == "HTTP_PROXY" || env.Name == "HTTPS_PROXY" {
			if credsRegex.MatchString(env.Value) {
				t.Errorf("credentials left in env value %v", env)
			}
			if !redactedRegex.MatchString(env.Value) {
				t.Errorf("redacted not present in env value %v", env)
			}
		} else { // NO_PROXY
			if !reflect.DeepEqual(env.Value, ".cluster.local") {
				t.Errorf("NO_PROXY env value changed: %v", env)
			}
		}
	}
}

