//默认日志输出器
func DefaultLogger() *Logger {
	if _defaultLogger == nil {
		_defaultLogger = NewLogger(DefaultLoggerWriter(), fmt.Sprintf("[%s] ", GetConfig().AppName), 0)
	}
	return _defaultLogger
