// Handles incoming connections.
func handleConnection(conn net.Conn) {
  // close connection on function exit
  defer conn.Close()

  // set read deadline for connection
  conn.SetReadDeadline(time.Now().Add(60 * time.Second))

  // buffer for incoming data
  buffer := make([]byte, 1024)

  // loop to read data from connection
  for {
    // read data from connection
    n, err := conn.Read(buffer)
    // handle error during read
    if err != nil {
      handleError("Error reading from connection", err, true)
    }

    // write data back to connection
    _, err = conn.Write(buffer[:n])
    // handle error during write
    if err != nil {
      handleError("Error writing to connection", err, true)
    }
  }
}

