func checkAuth(ctx context.Context, h string) error {
	if os.Getenv("FLEXDEV_NOAUTH") != "" {
		return nil
	}

	u, err := user.CurrentOAuth(ctx,
		"https://www.googleapis.com/auth/cloud-platform",
