		SMTPAddress:      *smtpAddress,

		SpamdAddress:     *spamdAddress,

		DKIMKey:          *dkimKey,

		DKIMSelector:     *dkimSelector,

	}



	h := handler.PrepareHandler(config)



	server := &smtpd.Server{

		WelcomeMessage: *welcomeMessage,

		Handler:        h,

	}



	outbound.StartQueue(config)



	server.ListenAndServe(*bindAddress)

}

