	addrHex := hex.EncodeToString(addr)
	keyDirPath := filepath.Join(keysDirPath, addrHex)
	keyFilePath := filepath.Join(keyDirPath, addrHex)
	err = os.MkdirAll(keyDirPath, 0700) // read, write and dir search for user
