// Entry is an entry in the cache.
type Entry struct {
	Key   interface{}
	Value interface{}
}

// Add adds an element to the cache. If the cache is full, the least recently
// used element is evicted.
func (c *Cache) Add(key, value interface{}) {
	c.lk.Lock()
	defer c.lk.Unlock()

